export default {
  title: 'Components/Button/Button',
  component: Button,
  tags: ['autodocs'],
  argTypes: {
    variant: {
      control: 'select',
      options: VARIANTS,
    },
    size: {
      control: 'select',
      options: SIZES,
    },
    loading: {
      control: 'boolean',
    },
    disabled: {
      control: 'boolean',
    },
    fullWidth: {
      control: 'boolean',
    },
    icon: {
      control: 'object',
    },
    type: {
      control: 'text',
    },
  },
  args: { children: 'Make a wish', variant: 'primary', size: 'md' },
};

function Button({
  variant = "primary",
  size = "md",
  loading = false,
  disabled = false,
  fullWidth = false,
  icon,
  children,
  className,
  type = "button",
  ...props
}, forwardedRef) {
  const mergedNativeRef = useComposedRefs(forwardedRef);
  const isDisabled = disabled || loading;
  return (
    <button
      {...props}
      type={type}
      disabled={isDisabled}
      aria-busy={loading || undefined}
      className={cx(
        "cs-button",
        `cs-button--${variant}`,
        `cs-button--${size}`,
        fullWidth && "cs-button--full",
        isDisabled && "is-disabled",
        loading && "is-loading",
        className
      )}
     ref={mergedNativeRef} >
      {(icon || icon === 0) ? <span className="cs-button__icon" aria-hidden="true">{icon}</span> : null}
      <span className="cs-button__label">{children}</span>
      {loading ? <span className="cs-button__spinner" aria-hidden="true" /> : null}
    </button>
  );
}

{open ? (
        floating.render(<div ref={floatingRef} className="cs-combobox__popup">
        <ul className="cs-combobox__list" role="listbox" id={id} aria-label={label || (ariaLabelledBy ? undefined : t("label"))} aria-labelledby={control["aria-labelledby"]}>
          {shown.map((o, i) => (
            <li key={o.value} id={id + "-" + i} role="option" aria-selected={o.value === value} className={cx("cs-combobox__opt", i === hl && "hl")}
              onMouseEnter={() => setHl(i)} onMouseDown={(e) => { e.preventDefault(); pick(o); }}>{o.label}</li>
          ))}
        </ul>
        {!shown.length ? <div role="status" className="cs-combobox__empty">{t("empty")}</div> : null}
        </div>)
      ) : null}

key = (e) => {
    if (e.nativeEvent.isComposing || e.keyCode === 229) return;
    if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setHl((h) => (shown.length ? Math.min(shown.length - 1, h + 1) : 0)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setHl((h) => Math.max(0, h - 1)); }
    else if (e.key === "Enter") { if (open && shown[hl]) { e.preventDefault(); pick(shown[hl]); } }
  }

onDocEscape = (e) => {
    if (e.key !== "Escape" || e.isComposing || e.keyCode === 229) return;
    if (!layers.length) return;
    resort();
    const top = [...layers].reverse().find((layer) => layer.kind !== "toast");
    if (!top || typeof top.onEscape !== "function") return;
    // One stack owns dismissal across modal and registered nonmodal layers.
    e.preventDefault();
    e.stopPropagation();
    top.onEscape();
  }

function useOverlayLayer({
  open,
  kind = "modal",
  trapFocus = false,
  lockScroll,
  onEscape,
  panelRef,
  backdropRef,
  preferFocusSelector,
  restoreFocus = true,
  surfaceKey,
}) {
  const ctx = React.useContext(OverlayContext);
  const parentScope = React.useContext(overlayScopeContext);
  const mgr = ctx || getOverlayManager();
  const escapeRef = React.useRef(onEscape);
  escapeRef.current = onEscape;

  const scopeBinding = React.useRef(null);
  // Preserve ownership while an always-mounted portal trigger opens/closes. Rebinding
  // during close would briefly inert that trigger before focus restoration.
  useClientLayoutEffect(() => {
    const panelEl = panelRef?.current;
    const previous = scopeBinding.current;
    if (previous?.panelEl === panelEl && previous?.parentScope === parentScope) return;
    previous?.cleanup();
    scopeBinding.current = panelEl && parentScope
      ? { panelEl, parentScope, cleanup: mgr.registerScope({ panelEl, get parentEl() { return parentScope.current; } }) }
      : null;
  });
  useClientLayoutEffect(() => () => { scopeBinding.current?.cleanup(); scopeBinding.current = null; }, []);

  useClientLayoutEffect(() => {
    if (!open) return undefined;
    const restoreEl = typeof document !== "undefined" ? document.activeElement : null;
    const panel = panelRef && panelRef.current;
    const unregister = mgr.register({
      kind,
      lockScroll: lockScroll != null ? lockScroll : kind === "modal",
      onEscape: () => escapeRef.current && escapeRef.current(),
      restoreEl: restoreFocus ? restoreEl : null,
      panelEl: panel || null,
      backdropEl: backdropRef?.current || null,
      parentRef: parentScope,
    });

    // Only the innermost (top) layer should move focus / trap Tab — outer parents
    // run layout effects after children and must not steal focus from nested alerts.
    let detachTrap = () => {};
    const ownsModalFocus = mgr.activeModal()?.panelEl === panel;
    if (trapFocus && panel && ownsModalFocus && !mgr.focusScope().some((root) => root.contains(document.activeElement))) {
      const preferred =
        (preferFocusSelector && panel.querySelector(preferFocusSelector)) ||
        visibleFocusables([panel])[0] ||
        panel;
      preferred && preferred.focus && preferred.focus();
    }

    if (trapFocus && panel) {
      detachTrap = attachFocusTrap(panel, { isActive: () => mgr.activeModal()?.panelEl === panel, scopeElements: () => mgr.focusScope(), focusOrder: backwards => mgr.focusOrder({ backwards }) });
    }
    return () => {
      detachTrap();
      unregister();
    };
  }, [open, kind, trapFocus, lockScroll, mgr, panelRef, backdropRef, parentScope, preferFocusSelector, restoreFocus, surfaceKey]);

  return { manager: mgr, scope: open && panelRef ? panelRef : parentScope };
}

function attachFocusTrap(panelEl, { handleEscape = false, onEscape, isActive = () => true, scopeElements = () => [panelEl], focusOrder } = {}) {
  if (!panelEl) return () => {};
  const inside = (el) => scopeElements().some((root) => root?.contains(el));
  const focusables = (backwards = false) => focusOrder ? focusOrder(backwards) : visibleFocusables(scopeElements());
  const focusFirst = () => (focusables()[0] || panelEl).focus();
  const onFocus = (e) => { if (isActive() && !inside(e.target)) focusFirst(); };
  const k = (e) => {
    if (!isActive() || e.isComposing || e.keyCode === 229) return;
    if (handleEscape && e.key === "Escape" && !e.isComposing && e.keyCode !== 229) {
      e.preventDefault();
      onEscape && onEscape();
      return;
    }
    if (e.key !== "Tab") return;
    const f = focusables(e.shiftKey);
    if (!f.length) { e.preventDefault(); panelEl.focus(); return; }
    const active = document.activeElement;
    // Own intermediate movement too: WebKit can leave focus on body when
    // reverse-tabbing from a link to a button under its native tab preference.
    if (e.defaultPrevented) return;
    const index = f.indexOf(active);
    const next = index < 0 ? (e.shiftKey ? f.length - 1 : 0)
      : (index + (e.shiftKey ? -1 : 1) + f.length) % f.length;
    e.preventDefault();
    f[next].focus();
  };
  document.addEventListener("keydown", k);
  document.addEventListener("focusin", onFocus);
  return () => { document.removeEventListener("keydown", k); document.removeEventListener("focusin", onFocus); };
}

onTab = event => {
      const manager = getOverlayManager();
      const panel = panelRef.current;
      if (event.key !== "Tab" || event.defaultPrevented || event.isComposing || event.keyCode === 229 || manager.topDismissible()?.panelEl !== panel) return;
      const controls = manager.focusOrder({ backwards: event.shiftKey });
      const index = controls.indexOf(document.activeElement);
      if (index < 0) return;
      const next = index + (event.shiftKey ? -1 : 1);
      const target = controls[next] || (manager.activeModal() ? controls[(next + controls.length) % controls.length] : null);
      const native = manager.focusOrder({ backwards: event.shiftKey, logical: false });
      const nativeIndex = native.indexOf(document.activeElement);
      const nativeTarget = native[nativeIndex + (event.shiftKey ? -1 : 1)] || null;
      if (target === nativeTarget && !manager.activeModal()) return;
      if (target) { event.preventDefault(); target.focus(); }
      else if (manager.containsOwned(panel, event.target)) {
        // Let the browser leave the document at its logical edge. Temporarily
        // remove this host's stops so physical body order cannot loop back in.
        const stops = native.filter(el => manager.containsOwned(panel, el));
        const prior = stops.map(el => [el, el.getAttribute("tabindex")]);
        for (const el of stops) el.tabIndex = -1;
        const anchor = options.current.getTabAnchor?.() || anchorElement();
        const anchorControl = native.find(el => el === anchor || anchor?.contains(el));
        anchorControl?.focus();
        const restore = () => { for (const [el, value] of prior) if (el.isConnected && el.getAttribute("tabindex") === "-1") { if (value == null) el.removeAttribute("tabindex"); else el.setAttribute("tabindex", value); } };
        const timer = setTimeout(() => { restore(); restoreTimers.delete(timer); }, 0);
        restoreTimers.set(timer, restore);
      }
    }

